use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub const INSTALLED_PLUGIN_INDEX_VERSION: u32 = 1;
pub const INSTALLED_PLUGIN_INDEX_MIGRATION_VERSION: u32 = 1;
pub const INSTALLED_PLUGIN_INDEX_WARNING: &str =
    "DO NOT EDIT. This file is generated by OpenClaw from plugin manifests, install records, and config policy. Use `openclaw plugins registry --refresh`, `openclaw plugins install/update/uninstall`, or `openclaw plugins enable/disable` instead.";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum InstalledPluginIndexRefreshReason {
    Missing,
    StaleManifest,
    StalePackage,
    SourceChanged,
    PolicyChanged,
    Migration,
    HostContractChanged,
    ManualRefresh,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InstalledPluginIndexRecord {
    pub plugin_id: String,
    pub version: String,
    pub package_name: Option<String>,
    pub install_path: String,
    pub source_type: String, // e.g. "clawhub", "npm", "local"
    pub signature: Option<String>,
    pub enabled: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InstalledPluginIndex {
    pub version: u32,
    pub migration_version: u32,
    pub warning: String,
    pub refresh_reason: InstalledPluginIndexRefreshReason,
    pub records: HashMap<String, InstalledPluginIndexRecord>,
}

impl Default for InstalledPluginIndex {
    fn default() -> Self {
        Self {
            version: INSTALLED_PLUGIN_INDEX_VERSION,
            migration_version: INSTALLED_PLUGIN_INDEX_MIGRATION_VERSION,
            warning: INSTALLED_PLUGIN_INDEX_WARNING.to_string(),
            refresh_reason: InstalledPluginIndexRefreshReason::ManualRefresh,
            records: HashMap::new(),
        }
    }
}

#[derive(Clone, Default)]
pub struct InstalledPluginIndexStore {
    index: Arc<Mutex<InstalledPluginIndex>>,
}

impl InstalledPluginIndexStore {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_record(&self, record: InstalledPluginIndexRecord) {
        let mut idx = self.index.lock().unwrap();
        idx.records.insert(record.plugin_id.clone(), record);
    }

    pub fn get_record(&self, plugin_id: &str) -> Option<InstalledPluginIndexRecord> {
        let idx = self.index.lock().unwrap();
        idx.records.get(plugin_id).cloned()
    }

    pub fn remove_record(&self, plugin_id: &str) -> Option<InstalledPluginIndexRecord> {
        let mut idx = self.index.lock().unwrap();
        idx.records.remove(plugin_id)
    }

    pub fn set_enabled(&self, plugin_id: &str, enabled: bool) -> bool {
        let mut idx = self.index.lock().unwrap();
        if let Some(record) = idx.records.get_mut(plugin_id) {
            record.enabled = enabled;
            true
        } else {
            false
        }
    }

    pub fn list_enabled_records(&self) -> Vec<InstalledPluginIndexRecord> {
        let idx = self.index.lock().unwrap();
        idx.records.values().filter(|r| r.enabled).cloned().collect()
    }

    pub fn get_snapshot(&self) -> InstalledPluginIndex {
        self.index.lock().unwrap().clone()
    }
}

// ---------------------------------------------------------------------------
// Bundled Discovery Admission & Install Guards
// (from src/plugins/bundled-discovery-state.ts, bundled-install.ts, bundled-load-path-aliases.ts)
// ---------------------------------------------------------------------------

pub struct BundledDiscoveryAdmissionValidator;

impl BundledDiscoveryAdmissionValidator {
    pub fn assert_admission_valid(
        existing_plugin_ids: &std::collections::HashSet<String>,
        candidate_plugin_id: &str,
        candidate_path: &str,
    ) -> Result<(), String> {
        if candidate_plugin_id.trim().is_empty() {
            return Err("Candidate plugin ID cannot be empty".to_string());
        }
        if candidate_path.trim().is_empty() {
            return Err("Candidate plugin path cannot be empty".to_string());
        }
        if existing_plugin_ids.contains(candidate_plugin_id) {
            return Err(format!(
                "Duplicate plugin ID '{}' already admitted into discovery state",
                candidate_plugin_id
            ));
        }
        Ok(())
    }
}

pub struct BundledInstallGuard;

impl BundledInstallGuard {
    pub const IMMUTABLE_BUNDLED_PLUGINS: &'static [&'static str] = &[
        "telegram",
        "discord",
        "slack",
        "whatsapp",
        "signal",
        "imessage",
    ];

    pub fn is_immutable_bundled_plugin(plugin_id: &str) -> bool {
        Self::IMMUTABLE_BUNDLED_PLUGINS.contains(&plugin_id)
    }

    pub fn assert_can_uninstall_or_overwrite(plugin_id: &str, is_dev_mode: bool) -> Result<(), String> {
        if !is_dev_mode && Self::is_immutable_bundled_plugin(plugin_id) {
            return Err(format!(
                "Plugin '{}' is an immutable core bundled plugin and cannot be uninstalled or overwritten",
                plugin_id
            ));
        }
        Ok(())
    }
}

pub struct BundledLoadPathAliasResolver;

impl BundledLoadPathAliasResolver {
    pub fn resolve_alias(alias_map: &HashMap<String, String>, requested_path: &str) -> String {
        let clean = requested_path.trim_end_matches('/');
        if let Some(target) = alias_map.get(clean) {
            target.clone()
        } else {
            clean.to_string()
        }
    }
}

